<template>
    <div class="classify">
      <router-link to="/search" class="search-box"><i class="icon iconfont">&#xe61a;</i>搜索</router-link>
      <div class="classify-content" ref="listContent">
        <div class="nav-box">
          <div class="wrapper" ref="navList">
            <div class="list" >
              <div class="item" :class="{'active': index == typeIndex}" v-for="(item, index) in navList" :key="index" ref="navItem" @click="selectType(index)">
                <div class="txt">{{item.cat_name}}</div>
              </div>
            </div>
          </div>
        </div>
        <div class="goods-box">
          <div class="wrapper">
            <div class="list">
              <div class="goods-item" v-for="item in goodsList" :key="item.goods_id" @click="checkGoodsDetail(item.goods_id)">
                <div class="img-box">
                  <img class="goods-img" :src="item.image" alt="">
                  <span class="icon txt-icon new-user" v-if="item.is_new_user == 1">新人专享</span>
                  <img class="icon" v-else-if="item.labels && item.labels.type == 1" :src="item.labels.image" alt="">
                  <span class="icon txt-icon main-color-bg" :style="{background:'-webkit-linear-gradient(top,'+ item.labels.color +','+ item.labels.color2 +') !important'}" v-else-if="item.labels && item.labels.type == 0">{{item.labels.name}}</span>
                </div>
                <div class="desc-box">
                  <div class="name">{{ item.limit_buy == 0 ? '' : '【限购'+item.limit_buy+'份】' }}{{item.name}}</div>
                  <div class="total-buy">累计{{item.sell_count}}件</div>
                  <div class="price-box">
                    <div>
                      <span class="now now-icon main-color-font">¥</span>
                      <span class="now main-color-font">{{item.price}}</span>
                      <span class="old">¥{{item.old_price}}</span>
                    </div>
                    <AddToCart v-if="item.stock_status == 0 && item.is_no_start == 0 && item.limit_buy_status == 0" type="big" :goodsId="item.goods_id"/>
                  </div>
                </div>
                <div class="close-buy" v-if="item.stock_status == 1 || item.is_no_start == 1 || item.limit_buy_status == 1">
                  <div class="icon-box">
                    <div class="icon" v-if=" item.stock_status == 1 ">已抢光</div>
                    <div class="icon" v-else-if=" item.is_no_start == 1 || item.limit_buy_status == 1">未开始</div>
                  </div>
                </div>
              </div>
              <div class="scroll-tip" v-show="isLoading">上拉加载更多</div>
              <div class="scroll-tip" v-show="isComplete && goodsList.length > 10">已经到底了...</div>
            </div>
          </div>
        </div>
      </div>
    </div>
</template>

<script>
import BScroll from 'better-scroll'
import AddToCart from '../../components/AddToCart/AddToCart'
export default {
  name: 'Classify',
  data () {
    return {
      navScroll: '',
      goodsScroll: '',
      typeIndex: 0,
      listHeight: 0,
      navItemH: 0,
      navListStart: {},
      leader_id: '',
      navList: [],
      goodsList: [],
      page: 1,
      isLoading: false,
      isComplete: false,
      isAlive: false
    }
  },
  created () {
    this.leader_id = this.$util.storage.get('leader_id')
    this.getNavList()
  },
  activated () {
    if (this.leader_id != this.$util.storage.get('leader_id') && this.isAlive) {
      this.leader_id = this.$util.storage.get('leader_id')
      this.getNavList()
    }
    if (this.navList.length > 0 && this.$route.query.cat_id && this.$route.query.cat_id != this.navList[this.typeIndex].cat_id) {
      this.page = 1
      this.isLoading = this.isComplete = false
      this.getTypeIndex()
      this.getGoodsList()
    }
    this.isAlive = true
  },
  methods: {
    checkGoodsDetail (id) {
      this.$router.push({ path: '/goods', query: { goodsId: id, leaderId: this.leader_id } })
    },
    getTypeIndex () {
      for (var i = 0; i < this.navList.length; i++) {
        if (this.navList[i].cat_id == this.$route.query.cat_id) {
          this.typeIndex = i
          break
        }
      }
    },
    selectType (index) {
      if (index == this.typeIndex) {
        return
      }
      this.page = 1
      this.isLoading = false
      this.isComplete = false
      let direction = index > this.typeIndex
      this.typeIndex = index

      this.getGoodsList()

      let navListNow = this.$refs.navList.getBoundingClientRect()

      let distanceBottom = navListNow.bottom - this.listHeight - this.navListStart.top
      let distanceTop = this.navListStart.top - navListNow.y
      let distance = 0
      if (direction && distanceBottom > 0) {
        if (distanceBottom > this.navItemH / 2) {
          distance = Math.floor(-this.navItemH / 2 - distanceTop)
        } else {
          distance = Math.floor(-distanceBottom - distanceTop)
        }
        this.navScroll.scrollTo(0, distance, 300)
      } else if (!direction && distanceTop > 0) {
        if (distanceTop > this.navItemH / 2) {
          distance = Math.floor(this.navItemH / 2 - distanceTop)
        } else {
          distance = Math.floor(-distanceTop)
        }
        this.navScroll.scrollTo(0, distance, 300)
      }
    },
    async getNavList () {
      let res = await this.$api.getCategoryList({ leader_id: this.leader_id })
      if (!res) return
      this.navList = res
      this.getTypeIndex()
      this.getGoodsList()
      if (this.navScroll == '') {
        this.$nextTick(function () {
          this.navScroll = new BScroll('.nav-box', {
            click: true
          })
          this.listHeight = this.$refs.listContent.clientHeight
          this.navListStart = this.$refs.navList.getBoundingClientRect()
          this.navItemH = this.$refs.navItem[0].clientHeight
        })
      }
    },
    async getGoodsList (catId) {
      let param = {
        leader_id: this.leader_id,
        category_id: this.navList[this.typeIndex].cat_id,
        page: this.page
      }
      let res = await this.$api.getGoodsList(param)
      if (!res) return
      if (this.page == 1) {
        this.goodsList = []
      }
      this.goodsList = this.goodsList.concat(res)
      if (res.length < 20) {
        this.isComplete = true
        this.isLoading = false
      } else {
        this.isLoading = true
        this.page++
      }
      this.goodsScrollFunc()
    },
    goodsScrollFunc () {
      let _this = this
      this.$nextTick(function () {
        if (this.goodsScroll == '') {
          if (document.getElementById('skeleton')) {
            document.getElementById('skeleton').remove()
          }
          this.goodsScroll = new BScroll('.goods-box', {
            click: true,
            pullUpLoad: {
              threshold: 10
            }
          })
          this.goodsScroll.on('pullingUp', function () {
            if (_this.isLoading) {
              _this.getGoodsList()
            }
          })
        } else {
          this.goodsScroll.finishPullUp()
          this.goodsScroll.refresh()
        }
      })
    },
    setWxShare () {
      if (this.indexData) {
        let shareWxLink = window.location.protocol + '//' + window.location.host + '/packapp/community_group/redirect.html?app3Redirect=' + encodeURIComponent(window.location.protocol + '//' + window.location.host + '/packapp/community_group/index.html#/index?leaderId=' + this.leader_id)
        this.shareData = {
          title: document.title,
          sendFriendLink: shareWxLink,
          tTitle: document.title,
          wxappUrl: `/pages/index/index?redirect=webview&webview_url=${encodeURIComponent(shareWxLink)}&webview_title=${document.title}`,
          msgType: 'share'
        }
        this.$util.setWxShare(this.shareData)
      }
    }
  },
  components: {
    AddToCart
  }

}
</script>

<style lang="stylus" scoped>
.classify
  background #f8f8f8
  height 100%
  .search-box
    display block
    height 35px
    line-height 35px
    margin 10px 15px
    background #fff
    text-align center
    border-radius 20px
    color #666
    .icon
      font-size 14px
      padding-right 5px
  .classify-content
    border-top 1PX solid #efefef
    height calc(100% - 55px)
    background #fff
    overflow hidden
    flexbox()
    .nav-box
      height 100%
      width 90px
      .wrapper
        display inline-block
        width 100%
        .list
          .item
            color #666
            text-align center
            padding 18px 0
            &.active
              .txt
                color $color-main
                border-left 3px solid $color-main
                line-height 1.3
    .goods-box
      width calc(100% - 90px)
      border-left 1PX solid #efefef
      padding 0 10px
      .list
        .goods-item
          width 100%
          flexbox()
          padding 15px 0
          border-bottom 1PX solid #efefef
          position relative
          &:last-child
            border-bottom none
          .img-box
            width 80px
            height 80px
            overflow hidden
            flex-shrink 0
            position relative
            .goods-img
              width 100%
              height 100%
              object-fit cover
            .icon
              position absolute
              top 0
              left 0
              width 30px
              background $color-main
              &.txt-icon
                height 30px
                color #fff
                font-size 12px
                overflow hidden
                flexbox()
                align-items center
                justify-content center
              &.txt-icon.new-user
                box-sizing border-box
                padding-left 2px
                background -webkit-linear-gradient(top, #ff9204, #fe4022)
          .desc-box
            padding-left 10px
            flex-grow 1
            line-height 1.2
            position relative
            .name
              font-size 14px
              ellipsis(2)
              max-height 32px
            .total-buy
              margin 3px 0 5px
              color #999
            .group-buy
              font-size 10px
              background $color-main
              color #fff
              display inline-block
              padding 2px 8px
              border-radius 15px
            .price-box
              position absolute
              bottom -5px
              left 10px
              right 0px
              flexbox()
              justify-content space-between
              align-items center
              line-height 1.3
              .now
                font-size 18px
                font-weight bold
                color $color-main
                margin-right 5px
              .now-icon
                margin-right 0
                font-size 12px
              .old
                color #999999
                text-decoration line-through
              .num
                font-size 12px
                color #999999
          .close-buy
            position absolute
            top 0
            left 0
            right 0
            bottom 0
            background rgba(255, 255, 255, .4)
            padding 15px 0
            .icon-box
              width 80px
              height 80px
              padding 10px
              box-sizing border-box
              position relative
              .icon
                width 100%
                height 100%
                background rgba(0, 0, 0, .5)
                color #fff
                border-radius 50%
                flexbox()
                justify-content center
                align-items center
                font-size 14px
        .scroll-tip
          text-align center
          padding 10px
          color #bbb
</style>
